using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<ModelTrainingService>();

var app = builder.Build();

// Train the model at startup and log evaluation metrics
var trainer = app.Services.GetRequiredService<ModelTrainingService>();
var metrics = trainer.TrainAndEvaluate();
app.Logger.LogInformation(
    "Evaluation — MicroAccuracy: {Micro:P2}, MacroAccuracy: {Macro:P2}, LogLoss: {LogLoss:F4}, LogLossReduction: {Reduction:F4}",
    metrics.MicroAccuracy, metrics.MacroAccuracy, metrics.LogLoss, metrics.LogLossReduction);

// Register the pooled prediction engine (thread-safe for ASP.NET Core)
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(trainer.ModelPath);

// Rebuild the service provider so the pool is available to controllers
app = builder.Build();

app.MapControllers();
app.Run();

